const A='assets/robot-original/',views=[['overview','管控总览','overview.png'],['monitor','巡检监控','monitor.png'],['scenes','场景列表','scenes.png'],['deployment','场景部署','deployment.png'],['control','场景控制','control.png'],['configuration','控制配置','configuration.png'],['login','登录','login.jpeg']],q=new URLSearchParams(location.search),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const groups=[{name:'轮式机器人',x:552,y:447.701,w:192.45,h:183.9},{name:'吊轨机器人',x:655.051,y:150.098,w:201.351,h:220.148},{name:'吊轨机器人',x:1075.248,y:150.098,w:199.562,h:219.466},{name:'机器狗',x:1177.410,y:452.143,w:192.45,h:174.465},{name:'工作面巡检机器人',x:876.821,y:581.086,w:192.45,h:189.274}];
let view=views.some(x=>x[0]===q.get('view'))?q.get('view'):'overview',playing=false,still=q.get('still')==='1',ready=false,elapsed=0,last=0,hovered=-1,ended=false;const imgs={};
if(q.get('embed')==='1')document.body.classList.add('hide-controls');const wrap=document.createElement('div');wrap.className='original-wrap';document.body.append(wrap);const controls=document.createElement('div');controls.className='original-controls';document.body.append(controls);
function fit(){const h=document.body.classList.contains('hide-controls')?0:controls.getBoundingClientRect().height,s=Math.min(innerWidth/1920,(innerHeight-h)/1080);wrap.style.width=1920*s+'px';wrap.style.height=1080*s+'px';document.querySelector('.original-canvas').style.transform=`scale(${s})`}
function state(){return {type:'robot-original-motion-state',view,playing,still,ready,hovered,ended,progress:view==='monitor'?Math.min(1,elapsed/5000):0}}function notify(){if(parent!==window)parent.postMessage(state(),location.origin);const b=controls.querySelector('[data-action=motion]');if(b)b.textContent=playing?'暂停动效':view==='monitor'&&ended?'重播巡检':view==='overview'?'播放环绕':'播放巡检';const status=controls.querySelector('.motion-description');if(status)status.textContent=still?'静态原稿':view==='overview'?(hovered>=0?'悬停暂停 · 移开继续':'五组机器人顺时针环绕 · 悬停放大'):view==='monitor'?(ended?'本次巡检演示完成':'橙色机器人沿轨道向前移动 / 5秒'):'静态后台原稿'}
const mask=[[600,467],[608,465],[618,471],[673,490],[676,498],[683,500],[683,507],[673,510],[672,526],[665,536],[650,532],[617,520],[611,513],[610,490],[601,485],[598,479],[604,476]];
function polygon(ctx,points){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath()}
function drawInspection(){const cv=document.querySelector('.inspection-canvas');if(!cv||!imgs.monitor||!imgs.scene)return;const ctx=cv.getContext('2d');ctx.clearRect(0,0,1920,1080);ctx.drawImage(imgs.monitor,0,0,1920,1080);const s=1015*1.2039/1536,x=453-1015*.1123,y=119-674*.0005,progress=Math.min(elapsed/5000,1),dx=125*progress,dy=50*progress;ctx.save();ctx.beginPath();ctx.rect(454,120,1013,672);ctx.clip();ctx.translate(x,y);ctx.scale(s,s);ctx.save();polygon(ctx,mask);ctx.clip();ctx.drawImage(imgs.scene,110,44,1536-110,1024-44,0,0,1536-110,1024-44);ctx.restore();ctx.translate(dx,dy);polygon(ctx,mask);ctx.clip();ctx.drawImage(imgs.scene,0,0);ctx.restore()}
function drawOrbit(){const phase=elapsed/32000*Math.PI*2,cx=960,cy=455,rx=310,ry=190;document.querySelectorAll('.orbit-satellite').forEach((el,i)=>{const g=groups[i],u=(g.x+g.w/2-cx)/rx,v=(g.y+g.h/2-cy)/ry,angle=Math.atan2(v,u)+phase,initialR=Math.hypot(u,v),blend=Math.min(1,elapsed/1200),r=initialR+(1-initialR)*blend,x=cx+rx*r*Math.cos(angle),y=cy+ry*r*Math.sin(angle);el.style.left=(x-g.w/2)+'px';el.style.top=(y-g.h/2)+'px';el.style.zIndex=hovered===i?'70':y>cy+20?'40':'15';el.style.setProperty('--sat-scale',hovered===i?'1.14':'1');})}
function draw(){if(still)return;if(view==='overview')drawOrbit();if(view==='monitor')drawInspection()}
function tick(now){const dt=last?Math.min(now-last,70):0;last=now;if(ready&&playing&&!document.hidden&&hovered<0){elapsed+=dt;if(view==='monitor'&&elapsed>=5000){elapsed=5000;playing=false;ended=true;notify()}draw()}requestAnimationFrame(tick)}
async function render(){ready=false;hovered=-1;const v=views.find(v=>v[0]===view);let layers='';if(!still&&view==='overview')layers=`<div class="orbit-background"><img src="${A}background.png" alt=""></div><canvas class="orbit-panel-edge" width="818" height="14" aria-hidden="true"></canvas><img class="fixed-original-core" src="${A}core-alpha.png" alt="静止的原稿中央主视觉">${groups.map((g,i)=>`<button class="orbit-satellite" data-satellite="${i}" aria-label="${g.name}及底座，悬停或聚焦放大" style="left:${g.x}px;top:${g.y}px;width:${g.w}px;height:${g.h}px"><span class="satellite-art"><img src="${A}satellites-alpha.png" alt="${g.name}原稿" style="left:${552-g.x}px;top:${150.0977-g.y}px"></span></button>`).join('')}`;if(!still&&view==='monitor')layers='<canvas class="inspection-canvas" width="1920" height="1080" role="img" aria-label="橙色机器人沿原轨道移动五秒的巡检演示"></canvas>';
wrap.innerHTML=`<div class="original-canvas"><img class="original-image" src="${A+v[2]}" width="1920" height="1080" alt="${v[1]}原设计稿">${layers}</div>`;
controls.innerHTML=`<nav class="original-tabs" aria-label="原设计稿页面">${views.map(v=>`<button data-view="${v[0]}" role="tab" aria-selected="${view===v[0]}">${v[1]}</button>`).join('')}</nav><div class="original-actions"><span class="motion-description"></span><button data-action="motion" ${['overview','monitor'].includes(view)?'':'disabled'}>播放动效</button><button data-action="original">${still?'查看动效':'查看静态原稿'}</button><button data-action="full">全屏</button><a href="robot.html#motion">返回案例 ↗</a></div>`;fit();history.replaceState({},'',`?view=${view}${q.get('embed')==='1'?'&embed=1':''}${still?'&still=1':''}`);
for(const el of wrap.querySelectorAll('[data-satellite]')){const i=+el.dataset.satellite;el.addEventListener('pointerenter',()=>{hovered=i;drawOrbit();notify()});el.addEventListener('pointerleave',()=>{if(hovered===i){hovered=-1;drawOrbit();notify()}});el.addEventListener('focus',()=>{hovered=i;drawOrbit();notify()});el.addEventListener('blur',()=>{hovered=-1;drawOrbit();notify()})}
await Promise.allSettled([...wrap.querySelectorAll('img')].map(i=>i.decode()));if(view==='monitor'&&!still){await Promise.all(['monitor','scene'].map(async name=>{if(imgs[name])return;const img=new Image();img.src=name==='monitor'?A+'monitor.png':'assets/robot/scene-source.png';await img.decode();imgs[name]=img}));}const edge=wrap.querySelector('.orbit-panel-edge');if(edge){const ec=edge.getContext('2d'),source=wrap.querySelector('.original-image');ec.drawImage(source,552,757,818,14,0,0,818,14);ec.drawImage(source,1100,757,196,14,324,0,196,14);}ready=true;draw();notify()}
async function setView(v,autoplay=true){if(!views.some(x=>x[0]===v))return;view=v;elapsed=0;ended=false;still=false;playing=autoplay&&['overview','monitor'].includes(v);await render()}
async function play(){if(!['overview','monitor'].includes(view)){await setView('overview');return}if(still){still=false;elapsed=0;ended=false;playing=true;await render();return}if(ended){elapsed=0;ended=false}playing=true;notify()}function pause(){playing=false;notify()}async function toggle(){if(playing)pause();else await play()}
controls.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)return setView(b.dataset.view);if(b.dataset.action==='motion')await toggle();if(b.dataset.action==='original'){if(still)await play();else{pause();still=true;await render()}}if(b.dataset.action==='full'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}}});
addEventListener('message',async e=>{if(e.source!==parent||e.origin!==location.origin||e.data?.type!=='robot-original-motion-command')return;const a=e.data.action;if(a==='view')await setView(e.data.view);else if(a==='play')await play();else if(a==='pause')pause();else if(a==='toggle')await toggle();else if(a==='state')notify()});addEventListener('resize',fit);
window.OriginalRobot={setView,play,pause,toggle,seek(ms){elapsed=Math.max(0,ms);draw()},get view(){return view},get playing(){return playing},get still(){return still},get ready(){return ready},get elapsed(){return elapsed},get hovered(){return hovered},get ended(){return ended}};requestAnimationFrame(tick);render().then(()=>{if(!still&&!reduce&&q.get('autoplay')!=='0')play()});


